// heat flux magnitude from temperature
sqrt(d(T,x)^2 + d(T,y)^2 + d(T,z)^2)
// same with suffix notation
sqrt(Tx^2 + Ty^2 + Tz^2)
// tangential derivative of pressure along a wall
dtang(p, x)

// heat flux jump across an interior thin layer
up(ht.ntflux) - down(ht.ntflux)
// conductivity of the domain on the downside
down(ht.k_iso)
// stress in domain 2 on the shared boundary
side(2, solid.mises)

// temperature rise relative to the first time step
T - with(1, T)
// change between t = 10 s and t = 5 s
at(10, T) - at(5, T)
// use the flow from study 2 in a study 1 expression (different solver sequence)
withsol('sol2', spf.U, setval(Re, 1000))
// explicit coupling to the previous time step
prev(T, 1)

// weak contribution for a Robin-type condition: h*(T - Text) on a boundary
-h*(T - Text)*test(T)
// break the Jacobian coupling of an average-temperature feedback
h*(T - nojac(aveop1(T)))
// material function at a reference temperature
subst(mat1.def.k(T), T, 293.15)

// energy dissipated between 0 and 1 s (Global Evaluation)
timeint(0, 1, intop1(ec.Qh))
// cycle-averaged loss in a periodic steady state
timeavg(T_period*9, T_period*10, intop1(mf.Qh))
// Fourier series in an Analytic function
sum(sin(k*x)/k, k, 1, 20)
// numerical integral in a variable
integrate(exp(-s^2), s, 0, x)

// electrode potential with DC bias and AC perturbation
phis0 = E_dc + linper(10[mV])
// complex impedance from the perturbation solution
lindev(cd.es1.phisext)/lindev(intop1(cd.nIl))
// total field at phase 90 degrees: set phase in the dataset, then lintotal(T)

// particle force depending on local fluid temperature
F = -k_th*env(Tx)
// total heat rate through a fixed-temperature boundary (Surface Integration)
reacf(T)
// convolution using an integration coupling
intop1(nojac(rho)*exp(-((x-dest(x))^2+(y-dest(y))^2)/w^2))

// piecewise conductivity with a smooth switch at 300 K
k_low + (k_high - k_low)*flc2hs(T - 300[K], 5[K])
// avoid division by zero
if(abs(u) > 1e-9, F/u, 0)
// expression valid in both fluid and solid domains
if(isdefined(spf.U), spf.U, 0)

// time-averaged resistive loss density in the frequency domain
0.5*realdot(emw.Ex, emw.Jx) + 0.5*realdot(emw.Ey, emw.Jy) + 0.5*realdot(emw.Ez, emw.Jz)
// smoothed von Mises stress plot
ppr(solid.mises)
// objective sensitivity after a Sensitivity study
fsens(w_fin)

// time-dependent boundary condition
V0 = 10[V]*sin(2*pi*50[Hz]*t)
// instantaneous field at phase 45 degrees: set 'phase' in the dataset, then plot real(exp(i*phase)*emw.Ez)
// Global Evaluation after an eigenfrequency study
freq, imag(lambda), abs(imag(lambda))/(2*pi)

// normal component of current density on a boundary (Surface Integration)
ec.Jx*nx + ec.Jy*ny + ec.Jz*nz
// radial position dependent source in 3D
Q0*exp(-(x^2+y^2)/w^2)
// line graph x-axis: arc length
xdataexpr = s

// mesh size map
Surface plot expression: h
// number of elements in domain 2
Volume Integration of 1/meshvol over domain 2
// property that differs per domain without materials
if(dom == 1, 400, 0.5)

// total heat flux magnitude from the Heat Transfer interface
ht.tfluxMag
// terminal current of terminal 1 in Electric Currents
ec.I0_1
// thermal conductivity from the material definition
mat1.def.k
// coupling operator from another component
comp1.intop1(comp1.T)
// physical constants
k_B_const*T/e_const
